//! RECONSTRUCTED UNVERIFIED signed self read-marker adapter after reset.
use super::{PostgresPublicIdResolver,PublicApiError,PublicApiResult,PublicIdResolver,PublicUuid,ResourceKind,auth,query::{PublicQuery,QuerySchema}};
use crate::{error::ApiError,state::AppState};use axum::{Json,Router,body::to_bytes,extract::{OriginalUri,Path,RawQuery,Request,State},http::{HeaderMap,StatusCode},routing::get};
use manga_node::{auth as original_auth,db::Id,http_auth::HttpAuthError,library_view::{SnapshotChanged,ViewBudget}};use serde_json::{Value,json};use std::{collections::{BTreeMap,BTreeSet},time::Duration};
pub fn router()->Router<AppState>{Router::new().route("/manga/{id}/read",get(one).post(mutation_exception)).route("/manga/read",get(many))}
async fn mutation_exception()->PublicApiError{let mut e=PublicApiError::unsupported();e.detail="Public read/unread mutation requires the existing client-signed Nostr library commit; a plain MangaDex JSON body cannot authorize server signing".into();e}
fn query(raw:Option<&str>,many:bool)->PublicApiResult<PublicQuery>{
 for(key,_)in url::form_urlencoded::parse(raw.unwrap_or("").as_bytes()){if key!="head"&&!(many&&matches!(key.as_ref(),"ids[]"|"grouped")){return Err(PublicApiError::bad_request("Unsupported read-marker query parameter"));}}
 let q=PublicQuery::parse(raw,&QuerySchema{default_limit:0,max_limit:0,max_offset:0,scalar:if many{&["head","grouped"]}else{&["head"]},arrays:if many{&["ids[]"]}else{&[]},includes:&[],order:&[]})?;
 if q.first("head").is_some_and(|h|!original_auth::valid_hash(h)){return Err(PublicApiError::bad_request("The Nostr head must be an original event identifier"));}Ok(q)
}
fn unavailable()->PublicApiError{ApiError::unavailable().into()}
fn library_error(e:anyhow::Error)->PublicApiError{if e.is::<SnapshotChanged>(){return PublicApiError{status:StatusCode::CONFLICT,title:"Library snapshot changed",detail:"The current signed public library changed; refresh its head and try again".into()};}if e.is::<ViewBudget>(){return PublicApiError::bad_request("The original public-library read budget was exceeded");}if e.is::<HttpAuthError>(){return auth::map_error(e.downcast::<HttpAuthError>().unwrap());}unavailable()}
fn original_id(v:&str)->PublicApiResult<Id>{if !original_auth::valid_hash(v){return Err(unavailable());}hex::decode(v).ok().and_then(|b|b.try_into().ok()).ok_or_else(unavailable)}
async fn one(State(state):State<AppState>,OriginalUri(uri):OriginalUri,Path(id):Path<String>,RawQuery(raw):RawQuery,headers:HeaderMap,request:Request)->PublicApiResult<Json<Value>>{let q=query(raw.as_deref(),false)?;read(state,uri,headers,request,vec![PublicUuid::parse(&id)?],q,false).await}
async fn many(State(state):State<AppState>,OriginalUri(uri):OriginalUri,RawQuery(raw):RawQuery,headers:HeaderMap,request:Request)->PublicApiResult<Json<Value>>{let q=query(raw.as_deref(),true)?;let ids=q.ids("ids[]")?;if ids.is_empty(){return Err(PublicApiError::bad_request("At least one manga UUID is required"));}let grouped=q.boolean("grouped")?.unwrap_or(false);read(state,uri,headers,request,ids,q,grouped).await}
async fn read(state:AppState,uri:axum::http::Uri,headers:HeaderMap,request:Request,ids:Vec<PublicUuid>,q:PublicQuery,grouped:bool)->PublicApiResult<Json<Value>>{
 let method=request.method().to_string();let body=tokio::time::timeout(Duration::from_secs(5),to_bytes(request.into_body(),10240)).await.map_err(|_|PublicApiError::bad_request("Request body timeout"))?.map_err(|_|PublicApiError::bad_request("Request body budget"))?;
 let capability=auth::admitted_request(&state,&uri,&headers,&method,&body).await?;let resolver=PostgresPublicIdResolver::new(state.db.clone());let aliases=resolver.resolve_many(ResourceKind::Manga,&ids).await?;if ids.iter().any(|id|!aliases.contains_key(id)){return Err(PublicApiError::not_found());}
 let native_ids=aliases.values().map(|v|v.native_id.clone()).collect::<BTreeSet<_>>().into_iter().collect::<Vec<_>>();
 let rows=state.db.client().await?.query("SELECT m.id,m.protocol_series_id FROM platform.catalog_manga m WHERE m.id=ANY($1::text[]) AND m.deleted_at IS NULL AND m.state='published' AND m.protocol_source_visible AND m.protocol_series_id IS NOT NULL AND platform.protocol_source_is_visible(m.protocol_series_id)",&[&native_ids]).await.map_err(ApiError::from)?;
 if rows.len()!=native_ids.len(){return Err(PublicApiError::not_found());}let preferred=resolver.preferred_many(ResourceKind::Manga,&native_ids).await?;let mut series_to_manga=BTreeMap::new();let mut groups:BTreeMap<String,Vec<String>>=BTreeMap::new();
 for row in rows{let native:String=row.get(0);let source:String=row.get(1);let alias=preferred.get(&native).ok_or_else(unavailable)?.as_str().to_owned();series_to_manga.insert(source,alias.clone());groups.insert(alias,vec![]);}
 let series=series_to_manga.keys().map(|s|original_id(s)).collect::<PublicApiResult<Vec<_>>>()?;let future=state.protocol.public_read_markers(&capability,&series,q.first("head"));tokio::pin!(future);
 let snapshot=match tokio::time::timeout(Duration::from_secs(15),&mut future).await{Ok(r)=>r.map_err(library_error)?,Err(_)=>{let _=future.await;return Err(unavailable());}};
 let completed=snapshot.chapters.iter().map(|c|(hex::encode(c.chapter),hex::encode(c.series))).collect::<BTreeMap<_,_>>();let sources=completed.keys().cloned().collect::<Vec<_>>();
 let rows=state.db.client().await?.query("SELECT c.id,c.protocol_event_id,m.protocol_series_id FROM platform.catalog_chapters c JOIN platform.catalog_manga m ON m.id=c.manga_id WHERE c.protocol_event_id=ANY($1::text[]) AND m.id=ANY($2::text[]) AND c.deleted_at IS NULL AND NOT c.is_unavailable AND m.deleted_at IS NULL AND m.state='published' AND m.protocol_source_visible AND platform.protocol_source_is_visible(c.protocol_event_id) AND platform.protocol_source_is_visible(m.protocol_series_id) ORDER BY c.protocol_event_id",&[&sources,&native_ids]).await.map_err(ApiError::from)?;
 let chapter_ids=rows.iter().map(|r|r.get::<_,String>(0)).collect::<Vec<_>>();let mut chapter_aliases=BTreeMap::new();for batch in chapter_ids.chunks(super::postgres_identity::MAX_PUBLIC_ID_BATCH){chapter_aliases.extend(resolver.preferred_many(ResourceKind::Chapter,batch).await?);}
 let mut all=vec![];for row in rows{let native:String=row.get(0);let event:String=row.get(1);let series:String=row.get(2);if completed.get(&event)!=Some(&series){return Err(unavailable());}let alias=chapter_aliases.get(&native).ok_or_else(unavailable)?.as_str().to_owned();all.push(alias.clone());groups.get_mut(series_to_manga.get(&series).ok_or_else(unavailable)?).ok_or_else(unavailable)?.push(alias);}
 state.protocol.verify_read_marker_snapshot(&capability,&snapshot).await.map_err(library_error)?;
 Ok(Json(json!({"result":"ok","data":if grouped{json!(groups)}else{json!(all)},"nostr":{"pubkey":hex::encode(capability.principal()),"head":snapshot.head,"root":snapshot.root.map(hex::encode),"scope":"published_library_locally_projected_chapters"}})))
}
#[cfg(test)]mod tests{use super::*;#[test]fn read_marker_queries_are_exact_bounded_and_preserve_head_identity(){assert!(query(Some(&format!("head={}","a".repeat(64))),false).is_ok());for raw in["limit=10","offset=0","grouped=true","principal=other","head=bad","head=%ZZ"]{assert!(query(Some(raw),false).is_err());}assert!(query(Some("ids[]=11111111-1111-4111-8111-111111111111&grouped=true"),true).unwrap().boolean("grouped").unwrap().unwrap());assert!(query(Some("grouped=true&grouped=false"),true).is_err());}}
